  'recipe-masala-oats-boiled-eggs',
  'Savory Masala Oats with Boiled Eggs',
  'Nutritious rolled oats infused with Indian spices and sautéed vegetables, topped with protein-packed boiled eggs.',
  'Indian',
  ARRAY['eggetarian', 'high-protein', 'cutting-friendly']::text[],
  'breakfast',
  5,
  10,
  'easy',
  2,
  '["Heat 5g ghee in a pan and lightly sauté chopped onions and tomatoes.","Add 80g rolled oats along with turmeric, cumin, and black pepper; roast for 1 minute.","Pour in 2 cups of water and salt, bringing to a gentle boil on medium heat.","Cook for 4-5 minutes stirring occasionally until thick and creamy.","Halve 2 large boiled eggs and arrange neatly on top before serving."]'::jsonb,
  '["Toss in green peas, diced carrots, or baby spinach for extra micronutrients."]'::jsonb,
  '["https://pub-r2.calipartner.com/recipes/masala-oats-eggs/hero.jpg"]'::jsonb,
  'published',
  '{"calories":270,"protein":13.6,"carbs":30.4,"fat":10.6,"fiber":5,"sugar":2.7,"sodium_mg":66.7}'::jsonb,
  NULL,
  1,
  NOW(),
  NOW()
)
