) VALUES (
  'recipe-tandoori-spiced-chicken-breast',
  'Tandoori Spiced Grilled Chicken Breast',
  'Lean chicken breast marinated in thick curd, Kashmiri red chilli, kasuri methi, and grilled to tender perfection.',
  'North Indian',
  ARRAY['non-vegetarian', 'high-protein', 'cutting-friendly', 'gluten-free']::text[],
  'dinner',
  15,
  15,
  'medium',
  2,
  '["Score chicken breasts lightly with shallow diagonal cuts for deep marinade penetration.","In a bowl, mix 60g curd, Kashmiri chilli powder, garam masala, crushed kasuri methi, and salt.","Coat chicken thoroughly and let marinate for at least 30 minutes in the refrigerator.","Brush a cast-iron skillet or grill pan with 10g olive oil on medium-high heat.","Grill chicken for 6-7 minutes per side until the internal temperature reaches 74°C (165°F).","Rest for 5 minutes before slicing, then serve with lemon wedges and mint chutney."]'::jsonb,
  '["Resting the chicken after cooking locks in juices so it never dries out."]'::jsonb,
  '["https://pub-r2.calipartner.com/recipes/tandoori-chicken-breast/hero.jpg"]'::jsonb,
  'published',
  '{"calories":311.2,"protein":47.5,"carbs":1.3,"fat":11.5,"fiber":0,"sugar":1.3,"sodium_mg":124.6}'::jsonb,
  NULL,
  1,
  NOW(),
  NOW()
)
